import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Regression: the prefix-runs aggregation strategy's compiled filter ({@code NativeGroupStep.prefixRunFilter}) drove an
 * EXISTS adjacency-semijoin probe but was never closed — it bypasses the {@code NativeFilterLease} that releases every
 * other filter at evaluation end. The leaked probe held a dataset read stamp, so the dataset close spun forever in the
 * write-lock acquisition (the 2026-08-22 fuzz wedge: {@code aggregatesOverUnionsAndExistsConjunctions} sat for hours
 * with one core busy-yielding). The assertions mirror {@link LmdbNativeExistsFilterProbeCleanupTest}: zero live
 * semijoin probes after every result close, and the close itself must not wedge.
 */
public class LmdbNativePrefixRunFilterProbeCleanupTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI p1 = vf.createIRI(EX, "p1");
			IRI p2 = vf.createIRI(EX, "p2");
			for (int i = 0; i < 48; i++) {
				IRI s = vf.createIRI(EX, "s" + i % 12);
				conn.add(s, p1, i % 3 == 0 ? vf.createLiteral("v" + i) : vf.createIRI(EX, "o" + i));
				if (i % 2 == 0) {
					conn.add(s, p2, vf.createLiteral(i));
				}
			}
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	@Test
	public void prefixRunExistsConjunctionReleasesEveryNativeProbe() {
		// the fuzz round's flags: kernel rungs forced on with a zero row threshold puts the arbitrated
		// prefix-run proposal (whose filter drives the adjacency semijoin) in play on a small store
		String prevEnabled = System.getProperty("rdf4j.lmdb.janinoCodegen.enabled");
		String prevThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		String prevWcoj = System.getProperty("rdf4j.lmdb.wcoj.enabled");
		String prevUnions = System.getProperty("rdf4j.lmdb.janinoCodegen.unionSources");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.janinoCodegen.unionSources", "true");
		try {
			String[] queries = {
					"SELECT (COUNT(*) AS ?c) WHERE { ?s <" + EX + "p1> ?o . FILTER(EXISTS { ?s <" + EX
							+ "p2> ?z } && isLiteral(?o)) }",
					"SELECT ?s (COUNT(*) AS ?c) WHERE { ?s <" + EX + "p1> ?o . FILTER(EXISTS { ?s <" + EX
							+ "p2> ?z } && isLiteral(?o)) } GROUP BY ?s",
					"SELECT (COUNT(*) AS ?c) WHERE { ?s <" + EX + "p1> ?o . FILTER(EXISTS { ?s <" + EX
							+ "p2> ?z } && EXISTS { ?s <" + EX + "p1> ?w }) }",
			};
			try (SailRepositoryConnection conn = repository.getConnection()) {
				// several rounds so strategy arbitration explores every engine that can claim the filter
				for (int round = 0; round < 8; round++) {
					for (String query : queries) {
						List<BindingSet> result = assertTimeoutPreemptively(Duration.ofSeconds(30),
								() -> QueryResults.asList(conn.prepareTupleQuery(query).evaluate()),
								"query evaluation or result close wedged on a leaked dataset read stamp");
						assertThat(result).isNotEmpty();
						assertThat(((Literal) result.get(0).getValue("c")).longValue()).isGreaterThanOrEqualTo(0L);
						assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get())
								.as("native semijoin probes still held after result close (round %d, query %s)",
										round, query)
								.isZero();
					}
				}
			}
		} finally {
			restore("rdf4j.lmdb.janinoCodegen.enabled", prevEnabled);
			restore("rdf4j.lmdb.janinoCodegen.thresholdRows", prevThreshold);
			restore("rdf4j.lmdb.wcoj.enabled", prevWcoj);
			restore("rdf4j.lmdb.janinoCodegen.unionSources", prevUnions);
		}
	}

	private static void restore(String key, String previous) {
		if (previous == null) {
			System.clearProperty(key);
		} else {
			System.setProperty(key, previous);
		}
	}
}
